import { MaterializedView } from "@514labs/moose-lib";
import type { ProductEvent } from "../ProductEvent";

export interface TopProducts {
  product_id: string;
  views: number;
  carts: number;
  purchases: number;
  total_revenue: number;
}

export const TopProductsView = new MaterializedView<ProductEvent, TopProducts>({
  sourceTable: "ProductEvent",
  tableName: "TopProducts",
  select: `
    SELECT
      product_id,
      countIf(event_type = 'view') as views,
      countIf(event_type = 'cart') as carts,
      countIf(event_type = 'purchase') as purchases,
      sumIf(toFloat64OrZero(JSONExtractString(properties, 'price')), event_type = 'purchase') as total_revenue
    FROM ProductEvent
    GROUP BY product_id
  `,
});

import { MaterializedView } from "@514labs/moose-lib";
import type { ProductEvent } from "../ProductEvent";

export interface ConversionFunnel {
  step: string;
  unique_users: number;
  total_events: number;
}

export const ConversionFunnelView = new MaterializedView<ProductEvent, ConversionFunnel>({
  sourceTable: "ProductEvent",
  tableName: "ConversionFunnel",
  select: `
    SELECT
      event_type as step,
      uniqExact(user_id) as unique_users,
      count(*) as total_events
    FROM ProductEvent
    WHERE event_type IN ('view', 'cart', 'purchase')
    GROUP BY event_type
    ORDER BY CASE event_type
      WHEN 'view' THEN 1
      WHEN 'cart' THEN 2
      WHEN 'purchase' THEN 3
    END
  `,
});

import { MaterializedView } from "@514labs/moose-lib";
import type { ProductEvent } from "../ProductEvent";

export interface HourlyActivity {
  hour: string;
  event_type: string;
  event_count: number;
}

export const HourlyActivityView = new MaterializedView<ProductEvent, HourlyActivity>({
  sourceTable: "ProductEvent",
  tableName: "HourlyActivity",
  select: `
    SELECT
      formatDateTime(toStartOfHour(event_ts), '%Y-%m-%d %H:00:00') as hour,
      event_type,
      count(*) as event_count
    FROM ProductEvent
    GROUP BY toStartOfHour(event_ts), event_type
    ORDER BY hour, event_type
  `,
});

