### Define a MaterializedView in TypeScript

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/shared/guides/performant-dashboards/phase-2-optimization.mdx

Use the MaterializedView class to define how source tables are transformed and loaded into a target serving table. Ensure the select statement output matches the target table schema exactly.

```typescript
import { Int64, MaterializedView, OlapTable, sql } from "@514labs/moose-lib";
import { SourceTableA } from "./SourceTableA.model";
import { SourceTableB } from "./SourceTableB.model";

// ... serving table interface and OlapTable definition from Checkpoint 1 ...

export const ServingMV = new MaterializedView<ServingTableSchema>({
  selectStatement: sql`
    SELECT
      a.id,
      b.name,
      toDate(a.created_at) AS day,
      count() AS total,
      sumIf(1, a.status = 'complete') AS completed
    FROM ${SourceTableA} a
    JOIN ${SourceTableB} b ON b.id = a.ref_id
    GROUP BY a.id, b.name, day
  `,
  targetTable: ServingTable,
  materializedViewName: "<ServingTable>MV",
  selectTables: [SourceTableA, SourceTableB],
});
```

--------------------------------

### MaterializedView Creation

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/reference/index.mdx

Creates a materialized view in ClickHouse for write-time transformations.

```typescript
// Basic usage
export const view = new MaterializedView<UserStatistics>({
  selectStatement: "SELECT user_id, COUNT(*) as event_count FROM user_events GROUP BY user_id",
  tableName: "user_events",
  materializedViewName: "user_statistics",
  orderByFields: ["user_id"]
});
```

```python
# Basic usage
view = MaterializedView[UserStatistics](MaterializedViewOptions(
    select_statement="SELECT user_id, COUNT(*) as event_count FROM user_events GROUP BY user_id",
    table_name="user_events",
    materialized_view_name="user_statistics",
    order_by_fields=["user_id"]
))
```

--------------------------------

### Define AggregatingMergeTree Schema and View in TypeScript

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/olap/model-materialized-view.mdx

Use the Aggregated type to map ClickHouse aggregate states to TypeScript interfaces and define the MaterializedView.

```typescript
import { MaterializedView, ClickHouseEngines, Aggregated, sql } from "@514labs/moose-lib";


interface MetricsById {
  id: string;
  /**
   * Result of avgState(events.rating)
   *   - avgState(number) returns number, so model the type as number
   *   - Aggregated arg type is [number] because the column (events.rating) is a number
   *   - Aggregated function name is "avg"
   */
  avg_rating: number & Aggregated<"avg", [number]>;
  /** 
  * Result of uniqExactState(events.user_id)
  *  - uniqExact returns an integer; use number & ClickHouseInt<"uint64"> for precision
  *  - Aggregated arg type is [string] because the column (events.user_id) is a string
  *  - Aggregated function name is "uniqExact"
  */
  daily_uniques: number & ClickHouseInt<"uint64"> & Aggregated<"uniqExact", [string]>;
}

//  All Aggregate Functions in this query have a [functionName][State]() suffix.
const stmt = sql.statement`
  SELECT
    ${events.columns.id} AS id,
    avgState(${events.columns.rating})      AS avg_rating,
    uniqExactState(${events.columns.user_id}) AS daily_uniques
  FROM ${events}
  GROUP BY ${events.columns.id}
`;


new MaterializedView<MetricsById>({
  selectStatement: stmt,
  selectTables: [events],
  targetTable: {
    name: "metrics_by_id",
    engine: ClickHouseEngines.AggregatingMergeTree,
    orderByFields: ["id"],
  },
  materializedViewName: "mv_metrics_by_id",
});
```

--------------------------------

### TypeScript Materialized View for Aggregated Tables

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/olap/model-materialized-view.mdx

Defines a materialized view in TypeScript for an AggregatingMergeTree table, using stateful aggregation functions.

```typescript
import { MaterializedView, ClickHouseEngines, Aggregated, sql } from "@514labs/moose-lib";

interface MetricsById {
  id: string;
  avg_rating: number & Aggregated<"avg", [number]>;
  total_reviews: number & Aggregated<"sum", [number]>;
}

const aggStmt = sql.statement`
  SELECT
    ${reviews.columns.id} AS id,
    avgState(${reviews.columns.rating}) AS avg_rating,
    countState(${reviews.columns.id})   AS total_reviews
  FROM ${reviews}
  GROUP BY ${reviews.columns.id}
`;

const mv = new MaterializedView<MetricsById>({
  selectStatement: aggStmt,
  selectTables: [reviews],
  targetTable: {
    name: "metrics_by_id",
    engine: ClickHouseEngines.AggregatingMergeTree,
    orderByFields: ["id"],
  },
  materializedViewName: "mv_metrics_by_id",
});
```

--------------------------------

### Define Kafka Source and Materialized View in TypeScript

Source: https://github.com/514-labs/moosestack/blob/main/apps/framework-docs-v2/content/moosestack/engines/kafka.mdx

Use this TypeScript code to define a Kafka table for consuming data and a Materialized View to persist it. Ensure Kafka is running and accessible at the specified broker address.

```typescript
import { OlapTable, ClickHouseEngines, MaterializedView, sql } from '@514labs/moose-lib';

interface KafkaEvent {
  eventId: string;
  userId: string;
  timestamp: number; // Unix seconds for JSONEachRow
}

// Kafka table - reads from topic, doesn't persist
export const kafkaSource = new OlapTable<KafkaEvent>("kafka_events", {
  engine: ClickHouseEngines.Kafka,
  brokerList: "redpanda:9092",
  topicList: "events",
  groupName: "my_consumer_group",
  format: "JSONEachRow",
  settings: {
    kafka_num_consumers: "1",
  }
});

// MaterializedView moves data to MergeTree for persistence
const cols = kafkaSource.columns;
export const eventsMV = new MaterializedView<KafkaEvent>({
  tableName: "events_dest",
  materializedViewName: "events_mv",
  orderByFields: ["eventId"],
  selectStatement: sql.statement`SELECT ${cols.eventId}, ${cols.userId}, ${cols.timestamp} FROM ${kafkaSource}`,
  selectTables: [kafkaSource],
});
```

