#!/usr/bin/env node

const readline = require('readline');

async function makeRequest(url) {
  try {
    const fetch = (await import('node-fetch')).default;
    const start = Date.now();
    const response = await fetch(url);
    const elapsed = Date.now() - start;
    const data = await response.json();
    return { data, elapsed, status: response.status };
  } catch (error) {
    return { error: error.message, elapsed: -1, status: 'error' };
  }
}

async function testPipeline() {
  console.log('🦌 Testing Moose Analytics Pipeline');
  console.log('=====================================');

  // Test all three consumption endpoints
  const endpoints = [
    { name: 'Top Products', url: 'http://localhost:4000/consumption/top-products?limit=5' },
    { name: 'Conversion Funnel', url: 'http://localhost:4000/consumption/conversion-funnel' },
    { name: 'Hourly Activity', url: 'http://localhost:4000/consumption/hourly-activity?hours=24' }
  ];

  for (const endpoint of endpoints) {
    console.log(`\n📊 Testing ${endpoint.name}...`);
    const result = await makeRequest(endpoint.url);

    if (result.error) {
      console.log(`❌ Error: ${result.error}`);
    } else {
      console.log(`✅ Status: ${result.status}`);
      console.log(`⚡ Response time: ${result.elapsed}ms`);
      console.log(`📋 Data: ${JSON.stringify(result.data, null, 2).slice(0, 200)}...`);
    }
  }

  console.log('\n🎯 Pipeline verification complete!');
}

testPipeline();

